import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import Home from './pages/Home';
import Matchmaker from './pages/Matchmaker';
import WatchParty from './pages/WatchParty';

function App() {
    return (
        <Router>
            <div style={styles.appContainer}>

                {/* Üst Navigasyon Çubuğu (Navbar) */}
                <header style={styles.header}>
                    <div style={styles.brandContainer}>
                        <Link to="/" style={styles.logoLink}>
                            <span role="img" aria-label="movie">🎬</span> CineSense
                        </Link>
                    </div>

                    <nav style={styles.navLinks}>
                        <Link to="/" style={styles.navLink}>Ana Sayfa</Link>
                        <Link to="/matchmaker" style={styles.navLink}>Bireysel Eşleştirici</Link>
                        <Link to="/watch-party" style={styles.navLinkParty}>🍿 Watch Party</Link>
                    </nav>
                </header>

                {/* Ana İçerik Alanı ve Sayfa Rotaları */}
                <main style={styles.mainContent}>
                    <Routes>
                        {/* Ana Karşılama Sayfası */}
                        <Route path="/" element={<Home />} />

                        {/* Tekli Kullanıcı AI Öneri Sayfası */}
                        <Route path="/matchmaker" element={<Matchmaker />} />

                        {/* Çoklu Kullanıcı Ortak Öneri Sayfası */}
                        <Route path="/watch-party" element={<WatchParty />} />
                    </Routes>
                </main>

                {/* Alt Bilgi Alanı (Footer) */}
                <footer style={styles.footer}>
                    <p>© 2026 CineSense - AI-Powered Movie Matchmaker. Tüm Hakları Saklıdır.</p>
                </footer>

            </div>
        </Router>
    );
}

// Merkezi Görsel Stil Tanımlamaları
const styles = {
    appContainer: {
        fontFamily: "'Inter', sans-serif",
        backgroundColor: '#f4f4f9',
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        color: '#333'
    },
    header: {
        backgroundColor: '#111',
        color: '#fff',
        padding: '15px 40px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
        position: 'sticky',
        top: 0,
        zIndex: 1000
    },
    brandContainer: {
        fontSize: '24px',
        fontWeight: 'bold'
    },
    logoLink: {
        color: '#fff',
        textDecoration: 'none',
        display: 'flex',
        alignItems: 'center',
        gap: '10px'
    },
    navLinks: {
        display: 'flex',
        alignItems: 'center',
        gap: '25px'
    },
    navLink: {
        color: '#ccc',
        textDecoration: 'none',
        fontSize: '16px',
        fontWeight: '500',
        transition: 'color 0.2s',
        cursor: 'pointer'
    },
    navLinkParty: {
        color: '#fff',
        backgroundColor: '#6f42c1',
        padding: '8px 16px',
        borderRadius: '20px',
        textDecoration: 'none',
        fontSize: '15px',
        fontWeight: 'bold',
        boxShadow: '0 2px 6px rgba(111, 66, 193, 0.3)',
        transition: 'opacity 0.2s'
    },
    mainContent: {
        flex: 1,
        padding: '40px 20px',
        backgroundColor: '#f8f9fa'
    },
    footer: {
        backgroundColor: '#111',
        color: '#666',
        textAlign: 'center',
        padding: '15px 20px',
        fontSize: '14px',
        borderTop: '1px solid #222'
    }
};

export default App;
